def _ridge(g, target, penalty):
    n = len(target)
    training = g[:n]
    normal = training.T @ training + penalty * np.eye(g.shape[1])
    normal[0, 0] -= penalty
    return g[n:] @ np.linalg.solve(normal, training.T @ target)
